<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {admin,date} from '../../../shared/api'
import {communityLength} from '../../../shared/communityTypes'
import type {CommunityContent,CommunityReport,CommunityWord} from '../../../shared/communityTypes'
import {useLoad} from '../../../shared/useLoad'
const tab=ref('contents'),contents=ref<CommunityContent[]>([]),reports=ref<CommunityReport[]>([]),words=ref<CommunityWord[]>([]),type=ref(''),status=ref(''),query=ref(''),wordDialog=ref(false),wordId=ref<string>(),term=ref(''),enabled=ref(true),{loading,error,run}=useLoad()
const statusLabel:Record<string,string>={published:'公开',hidden:'已隐藏',deleted:'已删除',pending:'待处理',handled:'已处理'}
const filtered=computed(()=>contents.value.filter(c=>(!type.value||c.type===type.value)&&(!status.value||c.status===status.value)&&(!query.value||(c.title||c.body).includes(query.value))))
// 操作列固定在右侧，窄屏横向浏览表格时仍可处理内容、举报和词条。
async function reload(){[contents.value,reports.value,words.value]=await Promise.all([admin<CommunityContent[]>('GET','/admin/community/contents'),admin<CommunityReport[]>('GET','/admin/community/reports'),admin<CommunityWord[]>('GET','/admin/community/words')])}
const load=()=>run(reload);onMounted(load)
const hide=(item:CommunityContent)=>{if(!window.confirm('隐藏后，访客将无法查看该内容及讨论。确认隐藏？'))return;return run(async()=>{await admin('POST',`/admin/community/content/${item.id}/hide`);await reload()})}
const handle=(report:CommunityReport,action:'hide'|'dismiss')=>run(async()=>{await admin('PUT',`/admin/community/reports/${report.id}`,{action});await reload()})
function editWord(word?:CommunityWord){wordId.value=word?.id;term.value=word?.term||'';enabled.value=word?.enabled??true;wordDialog.value=true}
const saveWord=()=>run(async()=>{if(!term.value.trim()||communityLength(term.value)>80)throw new Error('词条不能为空且最多80个字符');await admin(wordId.value?'PUT':'POST',`/admin/community/words${wordId.value?'/'+wordId.value:''}`,{term:term.value,enabled:enabled.value});wordDialog.value=false;await reload()})
const toggle=(word:CommunityWord)=>run(async()=>{await admin('PUT',`/admin/community/words/${word.id}`,{term:word.term,enabled:!word.enabled});await reload()})
</script>
<template><div class="panel"><div class="section-title"><div><h2>社区管理</h2><p>查看帖子与评价、处理举报、维护恶意词库。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="tab">
 <el-tab-pane label="内容管理" name="contents"><div class="toolbar"><el-select v-model="type" placeholder="全部板块" clearable><el-option label="养宠交流" value="post"/><el-option label="店铺评价" value="review"/></el-select><el-select v-model="status" placeholder="全部状态" clearable><el-option v-for="s in ['published','hidden','deleted']" :key="s" :label="statusLabel[s]" :value="s"/></el-select><el-input v-model="query" placeholder="搜索标题或评价正文" clearable/></div><el-table :data="filtered" v-loading="loading"><el-table-column label="板块" width="100"><template #default="{row}">{{row.type==='post'?'交流':'评价'}}</template></el-table-column><el-table-column label="标题 / 内容" min-width="220" show-overflow-tooltip><template #default="{row}">{{row.title||row.body}}</template></el-table-column><el-table-column prop="authorName" label="作者" min-width="120"/><el-table-column label="评分" width="70"><template #default="{row}">{{row.rating||'—'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{statusLabel[row.status]}}</template></el-table-column><el-table-column label="发布时间" width="160"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="操作" fixed="right" width="160"><template #default="{row}"><RouterLink :to="`/community/${row.id}`"><el-button size="small">查看</el-button></RouterLink><el-button v-if="row.status==='published'" size="small" :disabled="loading" @click="hide(row)">隐藏</el-button></template></el-table-column></el-table></el-tab-pane>
 <el-tab-pane :label="`举报处理（${reports.filter(r=>r.status==='pending').length}）`" name="reports"><el-table :data="reports" v-loading="loading"><el-table-column prop="reason" label="举报原因" min-width="180" show-overflow-tooltip/><el-table-column prop="targetBody" label="被举报内容" min-width="200" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}">{{statusLabel[row.status]}}</template></el-table-column><el-table-column label="时间" width="160"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="操作" fixed="right" min-width="280"><template #default="{row}"><RouterLink :to="`/community/${row.contentId}`"><el-button size="small">查看内容</el-button></RouterLink><template v-if="row.status==='pending'"><el-button size="small" type="danger" :disabled="loading" @click="handle(row,'hide')">隐藏并处理</el-button><el-button size="small" :disabled="loading" @click="handle(row,'dismiss')">无需隐藏</el-button></template></template></el-table-column></el-table></el-tab-pane>
 <el-tab-pane label="恶意词库" name="words"><div class="toolbar"><el-button type="primary" @click="editWord()">新增词条</el-button><p>启用的词条用于拦截帖子、评价、评论及店铺回复。</p></div><el-table :data="words" v-loading="loading"><el-table-column prop="term" label="词条" min-width="180"/><el-table-column label="状态" width="100"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="更新时间" width="160"><template #default="{row}">{{date(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" fixed="right" width="180"><template #default="{row}"><el-button size="small" @click="editWord(row)">修改</el-button><el-button size="small" :disabled="loading" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-tab-pane>
 </el-tabs><el-dialog v-model="wordDialog" :title="wordId?'修改词条':'新增词条'" width="min(520px,90vw)"><el-form label-position="top" @submit.prevent="saveWord"><el-form-item label="词条"><el-input v-model="term" required maxlength="160"/><small>{{communityLength(term)}} / 80</small></el-form-item><el-form-item><el-checkbox v-model="enabled">启用此词条</el-checkbox></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button type="primary" native-type="submit" :loading="loading">保存词条</el-button></el-form></el-dialog></div></template>
